style.hiddenContent:
/* Preview frame shared by every view (from Lunch and Learn Simple's simple.css).
   Nothing in here is part of any demo. */
:root {
  font-family: ui-sans-serif, system-ui, -apple-system, 'Segoe UI', sans-serif;
  font-size: clamp(15px, 0.55vw + 9px, 21px);
  color: #1c1b22;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  margin: 0;
}

:focus-visible {
  outline: 3px solid #1f6feb;
  outline-offset: 2px;
}

/* The demo area fills the preview. */
.stage {
  position: relative;
  height: 100vh;
  overflow: hidden;
  background: #fff;
}

/* Note shown by unsupported.js when the browser lacks the feature. */
.unsupported {
  position: absolute;
  left: 0.8rem;
  bottom: 0.8rem;
  z-index: 100;
  display: flex;
  align-items: baseline;
  gap: 0.45rem;
  max-width: min(26rem, calc(100% - 1.6rem));
  margin: 0;
  padding: 0.35rem 0.75rem;
  font-size: 0.72rem;
  line-height: 1.4;
  color: #b42318;
  background: rgb(253 233 230 / 0.95);
  border: 1px solid #f1b8b0;
  border-radius: 0.6rem;
  pointer-events: none;
}

.unsupported::before {
  content: '';
  flex: none;
  width: 0.45rem;
  height: 0.45rem;
  background: #e5372b;
  border-radius: 50%;
}

.unsupported b {
  color: #8f1d14;
}

/* Looks only, shared by all three pages. */

.stage {
  background: #f1eee7;
}

.scroll {
  position: absolute;
  inset: 0;
  padding: 1.4rem;
  overflow-y: auto;
}

.tile {
  margin: 0;
  overflow: hidden;
  background: #fff;
  border: 1px solid #e4dfd4;
  border-radius: 0.9rem;
  box-shadow: 0 14px 30px -22px rgb(28 27 34 / 0.55);
}

.tile img {
  display: block;
  width: 100%;
  height: auto;
}

.tile figcaption {
  padding: 0.6rem 0.8rem 0.7rem;
  font-size: 0.9rem;
  font-weight: 700;
}

.tile figcaption span {
  display: block;
  font-size: 0.8rem;
  font-weight: 400;
  color: #77748a;
}

/* "Load more" (more.js) */
.more {
  display: block;
  margin: 1.4rem auto 0.4rem;
  padding: 0.65rem 1.3rem;
  font: inherit;
  font-weight: 700;
  color: #4636c9;
  cursor: pointer;
  background: #fff;
  border: 1px solid #d9d4f7;
  border-radius: 999px;
}

script.content:
const gallery = document.querySelector('.gallery');
const MIN_WIDTH = 200;
const GAP = 16;

function layout() {
  // How many lanes fit, and how wide each one is
  const width = gallery.clientWidth;
  const fit = Math.floor((width + GAP) / (MIN_WIDTH + GAP));
  const count = Math.max(1, fit);
  const laneWidth = (width - GAP * (count - 1)) / count;
  const laneHeights = new Array(count).fill(0);
  const tiles = [...gallery.children];

  tiles.forEach((tile) => (tile.style.width = laneWidth + 'px'));

  // Put every tile at the bottom of the shortest lane
  tiles.forEach((tile) => {
    const lane = laneHeights.indexOf(Math.min(...laneHeights));
    const x = lane * (laneWidth + GAP);
    const y = laneHeights[lane];
    tile.style.transform = `translate(${x}px, ${y}px)`;
    laneHeights[lane] += tile.getBoundingClientRect().height + GAP;
  });

  // Absolute tiles take no space, so set the height by hand
  gallery.style.height = Math.max(...laneHeights) - GAP + 'px';
}

// Lay out once, in the next frame. Inside the observer it
// would resize what it watches: "ResizeObserver loop" error.
let queued = false;
function schedule() {
  if (queued) return;
  queued = true;
  requestAnimationFrame(() => {
    queued = false;
    layout();
  });
}

// The gallery and every tile can change size (images, fonts)...
const resize = new ResizeObserver(schedule);
resize.observe(gallery);
[...gallery.children].forEach((tile) => resize.observe(tile));

// ...and new tiles can arrive
new MutationObserver((records) => {
  for (const record of records) {
    record.addedNodes.forEach((tile) => resize.observe(tile));
  }
  schedule();
}).observe(gallery, { childList: true });

layout();

